interface ActiveFindingState {
  finding: Finding;
  file: string;
  content?: string;
  sanitized?: string;
}

export default function GithubScanner({ token: initialToken, owner: initialOwner, repo: initialRepo, branch: initialBranch, onFileClick }: GithubScannerProps) {
