              fontFamily: 'var(--font-orbitron), sans-serif',
              color: accentColor,
            }}
          >
            {entry.type}
          </span>
          <span
            style={{
              fontSize: '8px',
              color: COLORS.textMuted,
              fontFamily: 'var(--font-share-tech-mono), monospace',
            }}
          >
            {formattedTimestamp}
          </span>
