        </div>
        <span style={{ fontSize: '9px', color: COLORS.textMuted }}>
          {totalEntries} EVENTS
        </span>
      </div>

      <div className="flex-1 overflow-y-auto dalek-scrollbar space-y-1 min-h-0">
